INSERT INTO `movies` (`id`, `tmdb_id`, `title`, `genre`, `plot`, `releaseDate`, `poster`, `trailerUrl`, `streamUrl`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1318447, 'Csúcsragadozó', 'Akció, Thriller', 'Egy gyászoló nő egyedül vág neki az ausztrál vadonnak, hogy feszegesse a saját határait, azonban prédává válik egy alattomos gyilkos beteges játékában.', '2026-04-24', '/whKPSACIlNMuYqLF4CnfHgjrPPz.jpg', NULL, NULL, '2026-04-29 13:22:12', '2026-04-29 13:22:12', NULL),
(2, 1226863, 'Super Mario Galaxis: A film', 'Kaland, Animációs, Vígjáték, Családi, Fantasy', 'A 2023-as Super Mario Bros.: A film sikere után érkezik a folytatás, amelyben új szereplők és új kalandok várnak ránk.  (Csillag Lajos)', '2026-04-01', '/g2m51KG5tYnSFRlRM1imyMhoexv.jpg', NULL, NULL, '2026-04-29 13:22:12', '2026-04-29 13:22:12', NULL),
(3, 1198994, 'Segítség!', 'Vígjáték, Horror, Thriller', 'Egy repülőgép-baleset után egy távoli szigeten reked egy tehetséges női alkalmazott és az idegesítő főnöke. A nőnek a túlélési képességeire kell hagyatkoznia, hogy mindkettőjüket megmentse, bár a köztük lévő nehézkes kapcsolat nem könnyíti meg a helyzetet.', '2026-01-22', '/jKROZwT4XhFTOgWStPCshtf2bfr.jpg', NULL, NULL, '2026-04-29 13:22:13', '2026-04-29 13:22:13', NULL),
(4, 1523145, 'Твоё сердце будет разбито', 'Dráma, Romantikus', '', '2026-03-26', '/iGpMm603GUKH2SiXB2S5m4sZ17t.jpg', NULL, NULL, '2026-04-29 13:22:14', '2026-04-29 13:22:14', NULL),
(5, 936075, 'Michael', 'Dráma, Zenei', 'Lebilincselő portré Michael Jacksonról, a bonyolult emberről és zseniális művészről, aki csodagyerekként született, felnőttként pedig a pop vitathatatlan királya lett. Egy átfogó kép a magánéletéről, de arról a művészi folyamatról is, amely alkotói munkásságát jellemezte.', '2026-04-22', '/duhEb8PTWYePg3VGR9ufN7AnxI2.jpg', 'https://www.youtube.com/watch?v=eN_TbEnGlMo', NULL, '2026-04-29 13:22:15', '2026-04-29 13:22:15', NULL),
(6, 980431, 'Aang legendája: Az utolsó léghajlító', 'Akció, Kaland, Animációs, Fantasy', 'Az új Avatar-film Aang és barátai történetét követi nyomon, immár fiatal felnőttként, évekkel azután, hogy az Avatar: Az utolsó léghajlító című sorozat eseményei után.', '2026-10-09', '/29Jdsak3SrwGds5k1t43kH6Khed.jpg', NULL, NULL, '2026-04-29 13:22:16', '2026-04-29 13:22:16', NULL),
(7, 83533, 'Avatar: Tűz és hamu', 'Kaland, Fantasy, Sci-Fi', 'Az RDA elleni pusztító háború és legidősebb fiuk elvesztése után Jake Sully és Neytiri új fenyegetéssel szembesül Pandorán: a hamu néppel, egy erőszakos és hataloméhes na\'vi törzzsel, amelyet a könyörtelen Varang vezet. Jake családjának a túlélésükért és Pandora jövőjéért kell harcolnia egy olyan konfliktusban, amely érzelmi és fizikai határaikig feszíti őket.', '2025-12-17', '/kIEYHWsBIn4gY7t1wR8dnGj1Y9e.jpg', NULL, NULL, '2026-04-29 13:22:17', '2026-04-29 13:22:17', NULL),
(8, 1292695, 'Meg fognak ölni', 'Akció, Vígjáték, Horror', 'Egy szinte átlagos nő munkát vállal egy elegáns, bár kissé titokzatos New York-i lakóházban. Aztán kénytelen rájönni, hogy néha úgy alkalmazzák az embert, hogy a lényeget pont nem mondják el előre. Ő takarítani jelentkezett, de a lakóknak áldozatra van szükségük. A ház egy démonkultusz kiismerhetetlen halálcsapdája. Az ott élők mind a kultusz tagjai, és havonta feláldoznak egy lányt a Sátánnak, aki a padlásukon húzza meg magát. A nő azonban szembeszáll velük: az egész ház csatatérré változik, és kezdődik a hajnalig tartó, őrült küzdelem, amelyben minden eszköz megengedett, és akit nem vágnak ketté, az felgyullad, lezuhan, szétfröccsen vagy törik. Csak egy feladat van: ki kell bírni reggelig.', '2026-03-25', '/oYpmoqz48PoouQmApxxMLQ7dXKA.jpg', 'https://www.youtube.com/watch?v=LbB1qO_mLuw', NULL, '2026-04-29 13:22:18', '2026-04-29 13:22:18', NULL),
(9, 1613798, 'Venganza', 'Akció, Thriller', '', '2026-02-26', '/ggJGx8fwwy21gEIXYusIlHcUn8z.jpg', NULL, NULL, '2026-04-29 13:22:19', '2026-04-29 13:22:19', NULL),
(10, 1327819, 'Agyugrász', 'Kaland, Animációs, Vígjáték, Családi, Sci-Fi', 'Egy állatbarát megragadja a lehetőséget, hogy olyan technológiát használjon, amely tudatát egy robothódba helyezi, és olyan rejtélyeket fedez fel az állatvilágban, amelyek minden elképzelését felülmúlják.', '2026-03-04', '/4u7fQkCOgKGuwwkjcw9fuu6Z14U.jpg', NULL, NULL, '2026-04-29 13:22:20', '2026-04-29 13:22:20', NULL),
(11, 687163, 'A Hail Mary-küldetés', 'Kaland, Sci-Fi', 'Ryland Grace, a természettudománytanár egy űrhajón ébred, fényévekre az otthonától, és semmire sem emlékszik – sem arra, hogy kicsoda, sem arra, hogyan került oda. Ahogy lassan visszanyeri az emlékeit, feltárul előtte a küldetése: meg kell fejtenie annak a rejtélyes anyagnak a titkát, amely a Nap kihunyását okozza. Tudományos ismereteire és szokatlan ötleteire támaszkodva kell megakadályoznia a Föld teljes kipusztulását… ám egy váratlan barátság révén talán mégsem kell egyedül szembenéznie a lehetetlennel.', '2026-03-15', '/wD0dkVerZMQu2uv7C9pPKXNB2pm.jpg', 'https://www.youtube.com/watch?v=rb3cFMAkNnA', NULL, '2026-04-29 13:22:21', '2026-04-29 13:22:21', NULL),
(12, 1352874, 'The Crucifix: Blood of the Exorcist', 'Horror', '', '2025-01-09', '/u3qOxvlykoTpurg1G8VOcawoePI.jpg', NULL, NULL, '2026-04-29 13:22:21', '2026-04-29 13:22:21', NULL),
(13, 1290821, 'A megmentő', 'Akció, Bűnügyi, Thriller', 'Egy isten háta mögötti skót szigeten él egy titokzatos férfi (Jason Statham). Senkivel sem tart kapcsolatot: a múltjával is szakítani akar.  Egyetlen kapcsolata a világgal egy kislány, aki hetente egyszer ételt visz neki. Az átmeneti harmóniát két veszély is fenyegeti: a közelgő hatalmas vihar, meg azok a deszantosok, akik éppen a bujkáló férfit keresik. A két baj egyszerre csap le, mindent felforgat, és nincs menekvés elölük: a férfi végül nem talál más kiutat, kénytelen áthágni a saját szigorú szabályait. Először csak a lányra akart vigyázni. Aztán már az otthonát kell védenie. Végül pedig a saját élete a tét és mindenkié, akit még szeretni tud.', '2026-01-28', '/mkXAIsmYA0Dk5UnrkQCr9CJiuNJ.jpg', 'https://www.youtube.com/watch?v=3AeSVegJ9Lg', NULL, '2026-04-29 13:22:22', '2026-04-29 13:22:22', NULL),
(14, 10867, 'Maléna', 'Dráma', 'Maléna a napsütötte, álmos szicíliai kisváros szépe, igéző és ellenállhatatlanul vonzó fiatal nő. Nemrég költözött ide, a férje a fronton van, és amikor csak végigmegy az utcán, férfiak vágyakozó tekintete és feleségek irigy pletykái kísérik minden lépését. Vézna, tizenéves srácok követik biciklijükön mindenhová, hogy lélegzetelállító szépségét minél tovább csodálhassák. A fiúk között van az élénk fantáziájú Renato, akit vágyai a fantázia világának váratlan magasságába röpítenek. Ám ahogy az évek telnek, Malénának - és az őt titkon csodáló Renatónak is - szembesülnie kell a könyörtelen valósággal.', '2000-10-27', '/muYSsqlD1sgoswIEtwDEal6u1TK.jpg', NULL, NULL, '2026-04-29 13:22:22', '2026-04-29 13:22:22', NULL),
(15, 1171145, 'A bűn útja', 'Bűnügyi, Thriller', 'A bűn útja egy ékszertolvaj (Chris Hemsworth) története, akinek aprólékosan megtervezett rablásai a napos Los Angelesben, a 101-es autópálya mentén, fejtörést okoznak a rendőrséget. Egy magányos nyomozó (Mark Ruffalo) a nyomába ered. Amikor útjaik keresztezik egy kiábrándult biztosítási ügynökét (Halle Berry), sorsdöntő döntéseket kell hozniuk egy halálos végjátékban, ahol milliók forognak kockán.', '2026-02-11', '/7ryVqPv2hKHgSWJPsMLnZlynHij.jpg', 'https://www.youtube.com/watch?v=hnJQDnPoMxw', NULL, '2026-04-29 13:22:23', '2026-04-29 13:22:23', NULL),
(16, 1297842, 'GOAT - Will, a bajnok', 'Animációs, Vígjáték, Családi', 'A bömball a világ legveszélyesebb sportja. Nagyvadak játsszák egy nagyon veszélyes pályán. És Will, a kis kecske százszor hallotta már életében, hogy hol van a kis állatok helye: a pálya szélén, vagy legfeljebb a lelátón. Ő azonban nem hajlandó elfogadni a prózai valóságot. A bömball legjobbjai közé akar kerülni. És mindent megér neki, hogy megvalósítsa az álmát.', '2026-02-11', '/97osc8Z8xBkgcG5iNXeXznLrLCe.jpg', 'https://www.youtube.com/watch?v=RUubvDNAKKk', NULL, '2026-04-29 13:22:24', '2026-04-29 13:22:24', NULL),
(17, 1470130, 'The Mortuary Assistant', 'Horror, Rejtély', 'Rebecca Owens, a halottkém-tudomány diplomás hallgatója éjszakai munkát vállal a River Fields Mortuary temetkezési vállalatnál. A rutinmunkának induló feladat hamarosan hátborzongató fordulatot vesz, amikor Rebecca szembesül a félelmetes természetfeletti erőkkel.  (Szarka Károly)', '2026-02-13', '/72AoFPC5TY4DfJwXXS9rPwPeReD.jpg', NULL, NULL, '2026-04-29 13:22:24', '2026-04-29 13:22:24', NULL),
(18, 1311031, 'Demon Slayer: Kimetsu No Yaiba Infinity Castle', 'Akció, Animációs, Fantasy', 'Indulj el az Infinity Castle-saga izgalmas első fejezetében, ahol titkok tárulnak fel és sorsok fonódnak össze, megteremtve az alapját egy olyan epikus kalandnak, amilyen még nem volt.  (Csillag Lajos)', '2025-07-18', '/tlNFKrkb0LzhnwvyiMSOoCB5dbj.jpg', 'https://www.youtube.com/watch?v=0pIu2hlvsec', NULL, '2026-04-29 13:22:25', '2026-04-29 13:22:25', NULL),
(19, 1601797, '¿Quieres ser mi novia?', 'Vígjáték, Romantikus', '', '2026-02-12', '/oscW8xV8EhRYj7iAhyVlBohKqxo.jpg', NULL, NULL, '2026-04-29 13:22:25', '2026-04-29 13:22:25', NULL),
(20, 350, 'Az ördög Pradát visel', 'Vígjáték, Dráma', 'Miranda Priestly a divat legnagyobb hatalmú úrnője, akinek ápolt kezeitől retteg a New York-i divatipar, aki senkit nem tűr meg útjában, ha tervei kivitelezéséről van szó, tökéletesen ellenőrzése alatt tartja a \"divat bibliáját\", a Runway Magazine-t, annak munkatársai életét teljesen megkeserítve. Miranda új munkatársa, Andy Sachs a frissen végzett főiskoláslány egyáltalán nem illik a képbe: szürke, jellegtelen, tökéletes ellentéte a cégnél dolgozó díváknak. Amikor belép a szerkesztőségbe, megdöbbenve jön rá, hogy a munka, amelyre jelentkezett nem elszántság és céltudatosság kérdése.', '2006-06-29', '/g3e7lOm1ismKHMyjgkRW9iKNrck.jpg', NULL, NULL, '2026-04-29 13:22:26', '2026-04-29 13:22:26', NULL),
(21, 1084242, 'Zootropolis 2.', 'Kaland, Animációs, Vígjáték, Családi, Rejtély', 'Judy Hoppsz nyomozó és ravasz partnere, Nick Wilde egy rejtélyes hüllő tekergőző nyomába szegődik, miután az fenekestül felforgatja Zootropolist. Az ügy felgöngyölítése érdekében Judy és Nick az állati város olyan szegleteibe merül alá, amik alaposan próbára teszik még formálódó munkakapcsolatukat.', '2025-11-26', '/qamAIfq1Bcm8pUqbpwLD3lhObT2.jpg', NULL, NULL, '2026-04-29 13:22:27', '2026-04-29 13:22:27', NULL),
(22, 1641319, 'Sniper: No Nation', 'Akció, Thriller', 'Brandon Beckett és Zero ügynök mentőakciót vezet Venezuelában, miután barátaikat túszul ejtették.', '2026-04-07', '/tUmARo0TZEK1EaSuS6dU35FhDyU.jpg', NULL, NULL, '2026-04-29 13:22:28', '2026-04-29 13:22:28', NULL),
(23, 1290417, 'Haragos természet', 'Horror, Thriller', 'A Henry nevű trópusi vihar a part felé haladva hurrikánná erősödik, így éri el Annieville városát Dél-Kaliforniában. A felszólításnak eleget téve a lakók többsége elhagyja a kisvárost, ám néhányan mégis maradnak. Lisa ugyan bármikor megszülhet, de túl későn eszmél és mire eljön a munkahelyéről, az utakat lezárják. Az édesanyját gyászoló Dakota  elindul otthonról, hogy biztonságos helyet keressen magának, de pánikba esik és inkább visszafordul. A három testvér, Ron, Dee és Will ugyancsak maradnak, mert nevelőapjuk szerint csupán egy kis eső várható, és az emberek feleslegesen pánikolnak. A tengerbiológus Dale kollégájával és egy televíziós stábbal száll motorcsónakba, hogy unokahúga, Dakota segítségére siessen, de megszűnik köztük a kommunikáció. Mikor az árhullám átszakítja a védműveket, elönti a víz a kisvárost és a házak között bikacápák jelennek meg zsákmányra vadászva.', '2026-04-10', '/ntf7iLKtl3Sg7ea3K8PEZJfypdz.jpg', NULL, NULL, '2026-04-29 13:22:30', '2026-04-29 13:22:30', NULL),
(24, 1084577, 'Bele a tököm', 'Akció, Kaland, Vígjáték', 'Övön aluli poénokkal teli, hajmeresztő vígjáték, amelyben két reklámszakember, Brad és Elijah új, mindent takaró óvszerével a VB szponzora akar lenni. A brazíliai ivászatból világméretű botrány lesz, és utána dühös szurkolók, bűnözők és hataloméhes hivatalnokok elől kell menekülniük, hogy megmentsék karrierjüket és élve hazajussanak.', '2026-04-15', '/l3726nLCXCXNu3FJ8pKjQM8gdhd.jpg', NULL, NULL, '2026-04-29 13:22:31', '2026-04-29 13:22:31', NULL),
(25, 1207162, 'Rise of the Conqueror', 'Akció, Kaland, Történelmi, Háborús', '', '2026-04-09', '/9cRE0DsM6CNIiY9Ah3cd8oc3n1Y.jpg', NULL, NULL, '2026-04-29 13:22:31', '2026-04-29 13:22:31', NULL),
(26, 1159559, 'Sikoly 7', 'Bűnügyi, Horror, Rejtély', 'Amikor egy új Ghostface-jelmezt öltött gyilkos bukkan fel az álmos kisvárosban, ahol Sidney Prescott új életet kezdett, a nő legsötétebb rémálmai válnak valóra: lánya lesz a következő célpont. Sidney bármeddig hajlandó elmenni, hogy megvédje családját, így hát szembenéz a múltjában rejlő borzalmakkal, hogy egyszer s mindenkorra véget vessen a vérontásnak.', '2026-02-25', '/eMe4e8jP0Hu5CUrZz4kkKO60yIB.jpg', NULL, NULL, '2026-04-29 13:22:32', '2026-04-29 13:22:32', NULL),
(27, 1304313, 'Lee Cronin: A múmia', 'Horror, Rejtély', 'Egy újságíró fiatal lánya nyomtalanul eltűnik a sivatagban. Nyolc évvel később a megtört családot váratlan sokk éri, amikor a lány visszatér hozzájuk. Az örömteli viszontlátás helyett azonban egy valóságos rémálom kezdődik.  (Gergo Horvath)', '2026-04-15', '/vXRiBTbjPE5reRDuVtSG9MVfVvB.jpg', 'https://www.youtube.com/watch?v=VbtjDXrI2Ls', NULL, '2026-04-29 13:22:34', '2026-04-29 13:22:34', NULL),
(28, 1419406, 'A sötétség peremén', 'Akció, Bűnügyi, Dráma, Thriller', 'A történet középpontjában Wong Tak Chung áll, egy visszavonult megfigyelési szakember, akit már rég maga mögött hagyott a szolgálat, amikor a rendőrség kénytelen újra elővenni. A város hiába van tele kamerákkal, arcfelismerő rendszerekkel és mindenféle korszerű eszközzel, egy profi bűnözői csapat mégis gond nélkül átsiklik a hálón.', '2025-08-16', '/vIoURIf7SS9olSdX0G90PdDGya6.jpg', NULL, NULL, '2026-04-29 13:22:35', '2026-04-29 13:22:35', NULL),
(29, 1242898, 'Predator: Halálbolygó', 'Akció, Kaland, Sci-Fi', 'A jövőben, egy távoli bolygón tartózkodó fiatal Ragadozót, Deket száműznek klánjából, mivel túl gyengének tartják. Útja során találkozik egy Thia nevű androiddal, aki a Weyland-Yutani társaság kreálmánya. Szövetséget kötnek és különböző kalandokba keverednek, miközben Dek egy különösen félelmetes lényt üldöz. Izgalmas, újragondolt fejezet a franchise történetében, ami egy jövőbeli, különösen halálos bolygóra, Genna-ra kalauzol minket.  A film legnagyobb ereje a merőben újító szemszögében rejlik, amelyben egy kitaszított Ragadozó kényszerű szövetséget köt egy Weyland szintetikussal. A történet feszes tempójú, ahol egyetlen felesleges perc sincs, garantálva a folyamatos feszültséget. És még a kevésbé akciódús képkockák is hozzáadnak a kerek egészhez.', '2025-11-05', '/y56DUYma05u4AMRxWAfWIqbvnep.jpg', NULL, NULL, '2026-04-29 13:22:35', '2026-04-29 13:22:35', NULL),
(30, 1368166, 'The Housemaid - A téboly otthona', 'Rejtély, Thriller', 'A téboly otthona című feszült thriller alapjául a világsikerű könyv szolgált. Egy olyan kifacsart világba repíti a nézőket, ahol a tökéletesség csak illúzió, semmi sem az, aminek látszik. Millie (Sydney Sweeney) megpróbál elmenekülni a múltja elől, ezért elfogad egy bentlakásos állást a gazdag Nina (Amanda Seyfried) és Andrew Winchester (Brandon Sklenar) házvezetőnőjeként. Ám ami valóságos álommelónak indul, gyorsan alakul át valami egészen szörnyű és veszélyes dologgá: szexi, csábító titkok, botrányok övezte hatalmi játszmává. Winchesterék zárt ajtói mögött egy sokkoló világ rejtőzik, csupa váratlan fordulattal, amelyeket a néző a film végéig találgathat.', '2025-12-18', '/4i6uEtxWBCvF32JFVuJWGDevZjy.jpg', 'https://www.youtube.com/watch?v=FRE02rSB1i0', NULL, '2026-04-29 13:22:36', '2026-04-29 13:22:36', NULL),
(31, 1010755, 'Hívatlanok - Utolsó fejezet', 'Horror, Thriller', 'A Hívatlanok trilógia fináléjában Maya (Madelaine Petsch) utoljára néz szembe a maszkos gyilkosokkal, akik kegyetlen módon megölték a szerelmét, és rá is kitartóan vadásznak. A brutális, végső leszámolásban nemcsak a túlélés a cél, a bosszú is hajtja a hősnőt, hogy elégtételt vegyen a szeretett férfiért és visszakapja az élete feletti irányítást.', '2026-02-05', '/yPHwX78mcwJw3I6YOJ9qh2wQBFr.jpg', NULL, NULL, '2026-04-29 13:22:36', '2026-04-29 13:22:36', NULL),
(32, 440249, 'After Porn Ends 2', 'Dokumentum', 'Az After the porn ends 2 ott folytatja, ahol az előző rész abbahagyta, így újra találkozhatunk a felnőtt filmek korosodó sztárjaival.', '2017-03-28', '/rfItXrtDGILwsCdmgVxX79phFuI.jpg', NULL, NULL, '2026-04-29 13:22:37', '2026-04-29 13:22:37', NULL),
(33, 502356, 'Super Mario Bros. - A Film', 'Kaland, Animációs, Vígjáték, Családi, Fantasy', 'A két brooklyni vízszerelő, Mario, és öccse, Luigi épp egy főcsapot akarnak megjavítani a föld alatt, amikor egy titokzatos csövön át egy csodálatos új világba kerülnek. Ám amikor a testvérek elszakadnak egymástól, Mario egy szédületes küldetésbe kezd, hogy megkeresse Luigit. Ebben segítségére van a Gombakirályság egyik alattvalója, Toad, és maga a határozott uralkodó, Peach hercegnő is, aki felkészíti Mariót a várható küzdelmekre a gonosz Bowserrel, és a koopák seregével…', '2023-04-05', '/1pwW73x00S5bi6upzbLGj5t5Vz2.jpg', 'https://www.youtube.com/watch?v=R7Y3RkYqhXY', NULL, '2026-04-29 13:22:38', '2026-04-29 13:22:38', NULL),
(34, 840464, 'Greenland: Az új menedék', 'Kaland, Sci-Fi, Thriller', 'Nem sokkal azután, hogy egy üstökös megtizedelte a Föld élővilágát, a Garrity család kénytelen hátrahagyni a grönlandi bunker nyújtotta biztonságot, és nekivágni a darabjaira hullott világnak, hogy új otthont találjanak.  A 2020-as a \'Greenland - Az utolsó menedék\' folytatására visszatért a rendezői székbe Ric Roman Waugh, míg a főbb szerepeket ezúttal is Gerard Butler és Morena Baccarin alakítják.', '2026-01-07', '/cqh16FjRjInJg36Fuh2pIk6s2pE.jpg', NULL, NULL, '2026-04-29 13:22:39', '2026-04-29 13:22:39', NULL),
(35, 1107166, 'Psycho Killer', 'Bűnügyi, Horror, Rejtély', 'Egy rendőrnő egy gyilkost üldöz, miután férje, egy rendőr, a sorozatgyilkos egyik áldozatává válik.', '2026-02-19', '/5xgxxmLivJXL8aF0HdZfpx8aAIo.jpg', NULL, NULL, '2026-04-29 13:22:40', '2026-04-29 13:22:40', NULL),
(36, 157336, 'Csillagok között', 'Kaland, Dráma, Sci-Fi', 'A nem túl távoli jövőben járunk, melyben bolygónk kezd lakhatatlanná válni. A föld alig hoz termést, rendszeresek a homokviharok, és lassan levegőt se lehet venni. Egy jelenés Coopert a NASA titkos telepére vezeti, ahol felkérik, hogy legyen a tagja annak a csapatnak, mely az emberiségnek új lakhelyet keres az univerzumban. Egy ismeretlen segítséggel megnyitott átjárón keresztül eljutnak egy galaxisba, ahol a közelben kialakult fekete lyuk miatt az idő is másképp telik. Ami nekik egy óra, az a végét járó földön éveket jelent. Alaposan meg kell hát gondolnia Coopernek, hogy a szóba jöhető bolygók közül melyikre látogat el, ha vissza akar térni a lányához, ahogy azt megígérte.', '2014-11-05', '/6KiSSndIMLj1swkpPNq2lYppDVQ.jpg', 'https://www.youtube.com/watch?v=EpUpK62PPR0', NULL, '2026-04-29 13:22:40', '2026-04-29 13:22:40', NULL),
(37, 1499885, 'The Red Book Ritual: Gates of Hell', 'Horror', '', '2025-09-18', '/dOLRsvnjOB6rCx6olyRsMT92PxI.jpg', NULL, NULL, '2026-04-29 13:22:41', '2026-04-29 13:22:41', NULL),
(38, 755898, 'Világok harca', 'Sci-Fi, Thriller', 'Egy földhözragadt sci-fi film a District 9 szellemében, amely a magánélet kontra megfigyelés témáit feszegeti.', '2025-07-29', '/yvirUYrva23IudARHn3mMGVxWqM.jpg', NULL, NULL, '2026-04-29 13:22:41', '2026-04-29 13:22:41', NULL),
(39, 1234731, 'Anakonda', 'Kaland, Vígjáték, Horror', 'Az 1997-ben megjelent Anakonda című thriller humoros újragondolása.  Doug (Jack Black) és Griff (Paul Rudd) kiskölyök koruk óta a legjobb haverok és világ életükben arról álmodoztak, hogy egyszer filmet csinálnak. Méghozzá gyerekkori kedvencük, az óriáskígyós-dzsungeles-horrorkaland, az Anakonda remake-jét. Kezdik úgy érezni, hogy öregszenek, ezért nem várnak tovább és minden pénzüket arra költik, hogy az eredeti helyszínen, az Amazonas őserdejében forgathassák újra a régi filmet. Vagyis: nincs pénzük, nem értenek a filmezéshez és fogalmuk sincs a környék veszélyeiről - minden a legjobban alakul! Kivéve, hogy az őserdőben valóban találkoznak egy elképesztő méretű kígyóval. A vicces káosz halálosan veszélyes káosszá válik. Végül is, sokszor mondták, hogy az életüket adnák a filmért…', '2025-12-24', '/sXzUrie6C6WPZ1MJQHWI8vq7Pwu.jpg', 'https://www.youtube.com/watch?v=5OuG5RjDzpQ', NULL, '2026-04-29 13:22:42', '2026-04-29 13:22:42', NULL),
(40, 1193501, 'Halálsíp', 'Horror, Rejtély', 'Egy csapat link tini az iskolában egy ősi azték tárgyra bukkan, nem sejtve, hogy az valójában egy elátkozott halálsíp. Rémséges dolgokat tapasztalnak, amik felfedik számukra a furcsa tárgy működését: a síp megfújása és az általa kiadott rémisztő hang az eljövendő halálukat idézi meg.  Ahogy a halottak száma gyarapodik körülöttük, a barátok kétségbeesett nyomozásba kezdenek a halálos ereklye eredete után. Kutatják a megoldást, hogyan lehetne az általuk elindított szörnyű eseményláncolatot megállítani.', '2026-01-20', '/ysyCqGLU5KDivsNGuxVedyrfgdf.jpg', 'https://www.youtube.com/watch?v=99J0YwGs_js', NULL, '2026-04-29 13:22:43', '2026-04-29 13:22:43', NULL),
(41, 1270125, 'Monster on a Plane', 'Vígjáték, Horror', '', '2024-11-07', '/9fBcq5WiH3z4YGjS2iVESRKxcW4.jpg', NULL, NULL, '2026-04-29 13:22:44', '2026-04-29 13:22:44', NULL),
(42, 1480387, 'Undertone', 'Horror, Rejtély', 'A „mindenféle hátborzongató” történetet tárgyaló podcast házigazdája beköltözik haldokló édesanyja házába, hogy ő legyen az elsődleges gondozója. Amikor a podcastjához tíz hangfelvételt küldenek egy gyermeket váró fiatal párról, akik paranormális zajokat tapasztalnak, rájön, hogy a nő története az ő sajátjának tükörképe, és minden egyes új felvétel a józan eszét karcolja, belerángatva őt egy olyan sorsba, amely elől nem menekülhet.', '2026-03-12', '/2PFgFMnrdCPXWiZl1PUvky7Mo9D.jpg', NULL, NULL, '2026-04-29 13:22:44', '2026-04-29 13:22:44', NULL),
(43, 7451, 'xXx', 'Akció, Kaland, Bűnügyi, Dráma, Thriller', 'Xander Cage (Vin Diesel), alias XXX saját hátborzongató mutatványairól szóló web-videók árusításával tölti nem éppen szokványos életét. Mind csupa hatásvadász, életveszélyes vállalkozás, melyek csupán rajongói és barátai körében emelik népszerűségét, ellenben egyre gyakrabban kerül összeütközésbe a törvénnyel. Xander nem sejti, hogy Augustus Gibbons (Samuel L. Jackson) személyében, a Nemzetbiztonsági Hivatal (NSA) folyamatos megfigyelés alatt tartja. Gibbonsnak pótolnia kell elveszített prágai emberét, akit beépítene az Anarchia 99 nevű titkos szervezetbe, hogy megakadályozza őket céljaik elérésében. Gibbons ügynök ideális jelöltre akad Xander Cage személyében, akinek szokatlan életmódja és bámulatra méltó fizikai adottságai tökéletesen alkalmassá teszik a feladatra, illetve tennék, ha a legcsekélyebb hajlandóságot is mutatná az új szerepkör iránt.', '2002-08-09', '/xeEw3eLeSFmJgXZzmF2Efww0q3s.jpg', NULL, NULL, '2026-04-29 13:22:45', '2026-04-29 13:22:45', NULL),
(44, 1265609, 'Ismeretlen támadók', 'Akció, Sci-Fi, Thriller', 'Az elit kiképzés utolsó, embert próbáló bevetésén egy katona egy óriási, földöntúli pusztítógép ellen vezeti egységét.', '2026-02-12', '/rV8KlXpQi0LruJglMcigiOu7Kqi.jpg', NULL, NULL, '2026-04-29 13:22:46', '2026-04-29 13:22:46', NULL),
